/*@
  requires N >= 1;
  requires \valid_read(x + (0 .. N - 1));
  requires \forall integer k; 0 <= k < N ==> INT_MIN <= x[k] < INT_MAX;
  assigns \nothing;
  ensures \forall integer k; 0 <= k < N ==> (x[k] & \result) == \result;
  ensures \forall integer v; (\forall integer k; 0 <= k < N ==> (x[k] & v) == v) ==> (\result & v) == v;
*/

/*@
  loop invariant 1 <= i <= N;
  loop invariant \forall integer k; 0 <= k < i ==> (x[k] & (int)res) == (int)res;
  loop invariant \forall integer v; (\forall integer k; 0 <= k < i ==> (x[k] & v) == v) ==> ((int)res & v) == v;
  loop assigns i, res;
  loop variant N - i;
*/

/*@
  loop invariant 0 <= i <= N;
  loop invariant \forall integer j; 0 <= j < i ==> INT_MIN <= x[j] < INT_MAX;
  loop assigns i, x[0 .. N - 1];
  loop variant N - i;
*/

/*@
  loop invariant 0 <= i <= N - 1;
  loop invariant temp == \at(x[0], LoopEntry);
  loop invariant \forall integer j; 0 <= j < i ==> x[j] == \at(x[j + 1], LoopEntry);
  loop invariant \forall integer j; i <= j < N ==> x[j] == \at(x[j], LoopEntry);
  loop assigns i, x[0 .. N - 2];
  loop variant N - 1 - i;
*/
